WHERE tenant_id = #{file.tenantId} AND deleted = 0
  AND storage_type = #{file.storageType} AND CAST(file_path AS BINARY) = CAST(#{file.filePath} AS BINARY)

    AND config_id = #{file.configId}
    AND config_id IS NULL
